/** A sheet's rate for one grade: a percent with two decimals. */
@Entity
@Table(name = "rate")
@IdClass(Rate.Key.class)
public class Rate {

    public record Key(String sheetId, String grade) implements Serializable {

        public Key() {
            this(null, null);
        }
    }

    @Id
    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Id
    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "rate", nullable = false)
    private BigDecimal rate;

    protected Rate() {
    }

    public Rate(String sheetId, String grade, BigDecimal rate) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.rate = rate;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    public BigDecimal getRate() {
        return rate;
    }

    public void setRate(BigDecimal rate) {
        this.rate = rate;
    }
}
